// Codegen for constants/. Pure: takes the source texts, returns the generated files.
import { parse as parseToml } from 'smol-toml'

/**
 * One limit. `linux` / `darwin` override `value` on that system; an entry with either says why in `whyLinux`
 * (`why_linux` in the TOML). Budgets take the macOS value: perf gates on the macOS reference machine only.
 */
export type LimitEntry = { value: number; unit: string; why: string; linux?: number; darwin?: number; whyLinux?: string }
export type GeneratedFile = { path: string; content: string }

const HEADER = 'GENERATED by `pnpm codegen` from constants/: do not edit.'

export function camel(snake: string): string {
  return snake.replace(/_([a-z0-9])/g, (_, c: string) => c.toUpperCase())
}

export function parseLimits(text: string): Record<string, LimitEntry> {
  const raw = parseToml(text) as Record<string, Record<string, unknown>>
  const out: Record<string, LimitEntry> = {}
  for (const [name, e] of Object.entries(raw)) {
    if (!/^[a-z][a-z0-9_]*$/.test(name)) throw new Error(`limits.toml: bad name ${name}`)
    const { value, unit, why, linux, darwin, why_linux: whyLinux, ...rest } = e
    const extra = Object.keys(rest)
    if (extra.length > 0) throw new Error(`limits.toml: ${name} has unknown field ${extra.join(', ')}`)
    if (typeof value !== 'number' || !Number.isFinite(value)) throw new Error(`limits.toml: ${name}.value must be a number`)
    if (typeof unit !== 'string' || typeof why !== 'string') throw new Error(`limits.toml: ${name} needs unit and why`)
    const entry: LimitEntry = { value, unit, why }
    for (const [system, v] of [['linux', linux], ['darwin', darwin]] as const) {
      if (v === undefined) continue
      if (typeof v !== 'number' || !Number.isFinite(v)) throw new Error(`limits.toml: ${name}.${system} must be a number`)
      if (Number.isInteger(v) !== Number.isInteger(value)) throw new Error(`limits.toml: ${name}.${system} must be ${Number.isInteger(value) ? 'an integer' : 'a fraction'}, like value`)
      entry[system] = v
    }
    if (entry.linux !== undefined || entry.darwin !== undefined) {
      if (typeof whyLinux !== 'string' || whyLinux === '') throw new Error(`limits.toml: ${name} has a per-system value and needs why_linux to say why`)
      entry.whyLinux = whyLinux
    } else if (whyLinux !== undefined) throw new Error(`limits.toml: ${name}.why_linux explains no linux or darwin value`)
    out[name] = entry
  }
  return out
}

export type Budget = Record<string, unknown> & { metric: string; unit: string }

export function parseBudgets(text: string, limits: Record<string, LimitEntry>): Record<string, Budget> {
  const raw = parseToml(text) as Record<string, Record<string, unknown>>
  const out: Record<string, Budget> = {}
  for (const [id, e] of Object.entries(raw)) {
    if (!/^P-[A-Z]+-\d+[a-z]?$/.test(id)) throw new Error(`budgets.toml: bad id ${id}`)
    const b: Record<string, unknown> = { ...e }
    for (const [k, v] of Object.entries(e)) {
      if (k.endsWith('_limit') && typeof v === 'string') {
        const lim = limits[v]
        if (!lim) throw new Error(`budgets.toml: ${id}.${k} names unknown limit ${v}`)
        delete b[k]
        b[k.slice(0, -'_limit'.length)] = lim.darwin ?? lim.value
      }
    }
    if (typeof b.metric !== 'string' || typeof b.unit !== 'string') throw new Error(`budgets.toml: ${id} needs metric and unit`)
    if ('covers' in b) throw new Error(`budgets.toml: ${id}.covers is not a budget field`)
    out[id] = b as Budget
  }
  return out
}

function tsLiteral(v: unknown): string {
  return JSON.stringify(v)
}

const perSystem = (e: LimitEntry) => e.linux !== undefined || e.darwin !== undefined

export function genLimitsTs(limits: Record<string, LimitEntry>): string {
  const lines = [`// ${HEADER}`, '']
  const anyPerSystem = Object.values(limits).some(perSystem)
  // the OS layer's choice, imported only when some number differs between systems
  if (anyPerSystem) lines.push("import { protocolOs } from '../os/index.ts'", '', "const linux = protocolOs.system === 'linux'", '')
  lines.push('/** Every cap, timeout and interval, keyed by camelCase name. */', 'export const L = {')
  for (const [name, e] of Object.entries(limits)) {
    lines.push(`  /** ${e.why} (${e.unit})${perSystem(e) ? ` Linux: ${e.whyLinux}` : ''} */`)
    lines.push(`  ${camel(name)}: ${perSystem(e) ? `linux ? ${e.linux ?? e.value} : ${e.darwin ?? e.value}` : e.value},`)
  }
  lines.push('} as const', '', 'export type LimitName = keyof typeof L', '')
  lines.push('/** Unit and reason of every limit, for reports; `whyLinux` where a system has its own value. */')
  lines.push('export const LIMIT_META: Record<LimitName, { unit: string; why: string; whyLinux?: string }> = {')
  for (const [name, e] of Object.entries(limits)) {
    const whyLinux = perSystem(e) ? `, whyLinux: ${tsLiteral(e.whyLinux)}` : ''
    lines.push(`  ${camel(name)}: { unit: ${tsLiteral(e.unit)}, why: ${tsLiteral(e.why)}${whyLinux} },`)
  }
  lines.push('}', '')
  return lines.join('\n')
}

export function genLimitsRs(limits: Record<string, LimitEntry>): string {
  const lines = [`// ${HEADER}`, '#![allow(dead_code)]', '']
  for (const [name, e] of Object.entries(limits)) {
    lines.push(`/// ${e.why} (${e.unit})`)
    if (perSystem(e)) lines.push(`/// Linux: ${e.whyLinux}`)
    const type = Number.isInteger(e.value) ? 'u64' : 'f64'
    // the OS layer's choice: `IS_LINUX` comes from the one `os` module that `cfg` picked
    const value = perSystem(e) ? `if crate::os::IS_LINUX { ${e.linux ?? e.value} } else { ${e.darwin ?? e.value} }` : `${e.value}`
    lines.push(`pub const ${name.toUpperCase()}: ${type} = ${value};`)
  }
  lines.push('')
  return lines.join('\n')
}

export function genBudgetsTs(budgets: Record<string, Budget>): string {
  const lines = [`// ${HEADER}`, '', '/** Performance budgets, keyed by the ID of the perf test that measures each. */', 'export const BUDGETS = {']
  for (const [id, b] of Object.entries(budgets)) {
    lines.push(`  ${tsLiteral(id)}: ${JSON.stringify(b)},`)
  }
  lines.push('} as const', '', 'export type BudgetId = keyof typeof BUDGETS', '')
  return lines.join('\n')
}

type TokenTree = Record<string, unknown>

function isLeaf(v: unknown): v is { $value: unknown } {
  return typeof v === 'object' && v !== null && '$value' in v
}

export function resolveRef(tokens: TokenTree, value: unknown, depth = 0): unknown {
  if (typeof value !== 'string') return value
  const m = /^\{([^}]+)\}$/.exec(value)
  if (!m) return value
  if (depth > 8) throw new Error(`tokens.json: reference cycle at ${value}`)
  let node: unknown = tokens
  for (const part of m[1]!.split('.')) {
    if (typeof node !== 'object' || node === null || !(part in node)) throw new Error(`tokens.json: unknown reference ${value}`)
    node = (node as Record<string, unknown>)[part]
  }
  if (!isLeaf(node)) throw new Error(`tokens.json: reference ${value} is not a token`)
  return resolveRef(tokens, node.$value, depth + 1)
}

export function genTokensCss(tokens: TokenTree): string {
  const vars: string[] = []
  const color = tokens.color as Record<string, { $value: string }>
  for (const [k, v] of Object.entries(color)) vars.push(`  --${k}: ${v.$value};`)
  const fonts = tokens.font as Record<string, { $value: string }>
  for (const [k, v] of Object.entries(fonts)) vars.push(`  --font-${k}: ${v.$value};`)
  const type = tokens.type as Record<string, { size: string; line: string; weight: number }>
  for (const [k, v] of Object.entries(type)) {
    vars.push(`  --type-${k}-size: ${v.size};`, `  --type-${k}-line: ${v.line};`, `  --type-${k}-weight: ${v.weight};`)
  }
  // `ratio`: unitless layout proportions (`--ratio-composer-top`), for calc() with a percentage
  for (const group of ['space', 'radius', 'size', 'motion', 'opacity', 'ratio'] as const) {
    const g = (tokens[group] ?? {}) as Record<string, { $value: string | number }>
    for (const [k, v] of Object.entries(g)) vars.push(`  --${group}-${k}: ${v.$value};`)
  }
  const shadow = tokens.shadow as Record<string, { $value: string }>
  for (const [k, v] of Object.entries(shadow)) vars.push(`  --shadow-${k}: ${v.$value};`)
  const term = (tokens.terminal as Record<string, Record<string, unknown>>)['kea-dark']!
  for (const [k, v] of Object.entries(term)) {
    if (isLeaf(v)) vars.push(`  --term-${k.replace(/[A-Z]/g, (c) => '-' + c.toLowerCase())}: ${String(v.$value)};`)
  }
  return `/* ${HEADER} */\n:root {\n${vars.join('\n')}\n}\n`
}

/** Plain values for code that cannot use CSS, such as main's window options and the token lint. */
export function genTokensTs(tokens: TokenTree): string {
  const px = (v: unknown) => {
    const m = /^(\d+(?:\.\d+)?)px$/.exec(String(v))
    if (!m) throw new Error(`not a px dimension: ${String(v)}`)
    return Number(m[1])
  }
  const color = tokens.color as Record<string, { $value: string }>
  const size = tokens.size as Record<string, { $value: string }>
  const space = tokens.space as Record<string, { $value: string }>
  const type = tokens.type as Record<string, { size: string }>
  const obj = (o: Record<string, unknown>) => `{\n${Object.entries(o).map(([k, v]) => `  ${tsLiteral(k)}: ${tsLiteral(v)},`).join('\n')}\n}`
  return [
    `// ${HEADER}`,
    '',
    '/** Colour tokens. */',
    `export const COLOR = ${obj(Object.fromEntries(Object.entries(color).map(([k, v]) => [k, v.$value])))} as const`,
    '',
    '/** Size tokens in px. */',
    `export const SIZE_PX = ${obj(Object.fromEntries(Object.entries(size).map(([k, v]) => [k, px(v.$value)])))} as const`,
    '',
    '/** The spacing scale in px. */',
    `export const SPACE_PX = [${Object.values(space).map((v) => px(v.$value)).join(', ')}] as const`,
    '',
    '/** Type sizes in px. */',
    `export const TYPE_SIZE_PX = [${Object.values(type).map((v) => px(v.size)).join(', ')}] as const`,
    '',
  ].join('\n')
}

export function genThemesTs(tokens: TokenTree): string {
  const terms = tokens.terminal as Record<string, Record<string, unknown>>
  const lines = [`// ${HEADER}`, '', '/** xterm.js ITheme objects, keyed by theme id. */', 'export const THEMES = {']
  for (const [id, t] of Object.entries(terms)) {
    const entries = Object.entries(t).filter(([, v]) => isLeaf(v)).map(([k, v]) => `    ${k}: ${tsLiteral(resolveRef(tokens, (v as { $value: unknown }).$value))},`)
    lines.push(`  ${tsLiteral(id)}: {`, ...entries, '  },')
  }
  lines.push('} as const', '', 'export type ThemeId = keyof typeof THEMES', '')
  return lines.join('\n')
}

/**
 * The bundled terminal themes as the settings schema lists them (the `terminal.theme` setting): id, name and colour
 * scheme, from each theme's `$extensions.kea`. Protocol cannot import `packages/terminal`, so it gets its own list.
 */
export function genThemeListTs(tokens: TokenTree): string {
  const terms = tokens.terminal as Record<string, { $extensions?: { kea?: { label?: unknown; scheme?: unknown } } }>
  const lines = [`// ${HEADER}`, '', '/** The bundled terminal themes: id, name and colour scheme. */', 'export const BUNDLED_THEMES = [']
  for (const [id, t] of Object.entries(terms)) {
    const kea = t.$extensions?.kea
    if (typeof kea?.label !== 'string' || (kea.scheme !== 'dark' && kea.scheme !== 'light')) throw new Error(`tokens.json: terminal.${id} needs $extensions.kea { label, scheme: dark | light }`)
    lines.push(`  { id: ${tsLiteral(id)}, label: ${tsLiteral(kea.label)}, scheme: ${tsLiteral(kea.scheme)} },`)
  }
  lines.push('] as const', '')
  return lines.join('\n')
}

export function genSyntaxTheme(tokens: TokenTree): string {
  const syntax = tokens.syntax as Record<string, unknown>
  const term = (tokens.terminal as Record<string, Record<string, { $value: string }>>)['kea-dark']!
  const color = tokens.color as Record<string, { $value: string }>
  const tokenColors: { name: string; scope: string[]; settings: { foreground: string; fontStyle?: string } }[] = []
  for (const [name, v] of Object.entries(syntax)) {
    if (name.startsWith('$') || !isLeaf(v)) continue
    const leaf = v as { $value: string; scopes: string[]; fontStyle?: string }
    const settings: { foreground: string; fontStyle?: string } = { foreground: String(resolveRef(tokens, leaf.$value)) }
    if (leaf.fontStyle) settings.fontStyle = leaf.fontStyle
    tokenColors.push({ name, scope: leaf.scopes, settings })
  }
  const theme = {
    $comment: HEADER,
    name: 'kea-dark',
    type: 'dark',
    colors: {
      'editor.background': color['surface-0']!.$value,
      'editor.foreground': term.foreground!.$value,
    },
    tokenColors,
  }
  return JSON.stringify(theme, null, 2) + '\n'
}

export type Sources = { limits: string; budgets: string; tokens: string }

export function generateAll(src: Sources): GeneratedFile[] {
  const limits = parseLimits(src.limits)
  const budgets = parseBudgets(src.budgets, limits)
  const tokens = JSON.parse(src.tokens) as TokenTree
  return [
    { path: 'packages/protocol/src/generated/limits.ts', content: genLimitsTs(limits) },
    { path: 'native/kea-helper/src/limits.rs', content: genLimitsRs(limits) },
    { path: 'tools/perf/src/generated/budgets.ts', content: genBudgetsTs(budgets) },
    { path: 'packages/ui/src/generated/tokens.css', content: genTokensCss(tokens) },
    { path: 'packages/terminal/src/generated/themes.ts', content: genThemesTs(tokens) },
    { path: 'packages/protocol/src/generated/themes.ts', content: genThemeListTs(tokens) },
    { path: 'packages/ui/src/generated/tokens.ts', content: genTokensTs(tokens) },
    { path: 'packages/ui/src/generated/syntax-theme.json', content: genSyntaxTheme(tokens) },
  ]
}
